  'corazon.perro.noche.0': 'Какой отличный был день! Правда? Правда? 🐶',
  'corazon.perro.noche.1': 'Тихая ночь… Я на страже! 🦴',
  'corazon.perro.rutina.0': '«{r}» в {h}! Ты справишься! 🎉',
  'corazon.perro.rutina.1': 'Не забудь про «{r}» в {h}! Гав! 🐶',
  'corazon.perro.generica.0': 'Обожаю этот дом! 🐶',
