  'ejercicio.ejDesc.press-banca': 'Лёжа на скамье, опусти штангу к груди и выжми её вверх до полного выпрямления рук.',
  'ejercicio.ejDesc.press-inclinado':
    'На наклонной скамье выжимай штангу или гантели, чтобы больше нагрузить верх груди.',
  'ejercicio.ejDesc.press-con-mancuernas': 'Лёжа, выжимай две гантели вверх — амплитуда больше, чем со штангой.',
  'ejercicio.ejDesc.aperturas-con-mancuernas': 'Лёжа, разводи руки дугой в стороны и своди обратно, чуть согнув локти.',
  'ejercicio.ejDesc.cruce-en-polea': 'Стоя между верхними блоками, своди руки перед собой, напрягая грудные мышцы.',
  'ejercicio.ejDesc.fondos-en-paralelas':
    'Вися на брусьях, опускайся, сгибая локти и наклоняя корпус вперёд, затем выжимайся обратно вверх.',
  'ejercicio.ejDesc.flexiones': 'Лицом вниз опускай грудь к полу, держа тело прямым, затем отжимайся обратно вверх.',
  'ejercicio.ejDesc.dominadas': 'Вися на перекладине, подтягивайся, пока подбородок не окажется над ней.',
  'ejercicio.ejDesc.jalon-al-pecho': 'Сидя у верхнего блока, тяни рукоять к груди, опуская локти вниз.',
  'ejercicio.ejDesc.remo-con-barra': 'В наклоне с прямой спиной тяни штангу к животу, напрягая мышцы спины.',
  'ejercicio.ejDesc.remo-con-mancuerna': 'Опираясь на скамью, тяни гантель к боку, не разворачивая корпус.',
  'ejercicio.ejDesc.remo-en-polea-baja': 'Сидя, тяни рукоять к животу, удерживая спину прямой.',
  'ejercicio.ejDesc.pull-over': 'Лёжа, опускай гантель за голову, затем возвращай её над грудью.',
  'ejercicio.ejDesc.face-pull': 'На блоке на уровне лица тяни канат к лбу, разводя локти в стороны.',
  'ejercicio.ejDesc.hiperextensiones': 'На скамье опускай корпус вниз и поднимай обратно, разгибая поясницу.',
  'ejercicio.ejDesc.press-militar': 'Стоя, выжимай штангу от плеч вверх над головой.',
  'ejercicio.ejDesc.press-arnold': 'Сидя, выжимай гантели над головой, разворачивая ладони от себя наружу.',
  'ejercicio.ejDesc.elevaciones-laterales': 'Стоя, поднимай гантели в стороны до уровня плеч.',
  'ejercicio.ejDesc.elevaciones-frontales': 'Стоя, поднимай гантель перед собой до уровня глаз.',
  'ejercicio.ejDesc.pajaros': 'В наклоне разводи руки в стороны, прорабатывая заднюю дельту.',
  'ejercicio.ejDesc.encogimientos': 'Стоя с весом, поднимай плечи к ушам и опускай их подконтрольно.',
  'ejercicio.ejDesc.curl-con-barra': 'Стоя, сгибай локти, поднимая штангу вверх, не раскачивая корпус.',
  'ejercicio.ejDesc.curl-con-mancuernas':
    'Стоя или сидя, поднимай гантели вверх, сгибая локти, поочерёдно или одновременно.',
