  'editor.pers.anim': 'Анимация',
  'editor.pers.animFlote': 'Движение заменяет естественное покачивание персонажа; приветственный жест остаётся.',
  'editor.pers.animSinPiezas': 'Чтобы создавать анимации по позам, собери тело из 3D-деталей на вкладке «Тело».',
  'room.cocina.desc': 'Питание: записывай приёмы пищи, БЖУ, воду и план на неделю.',
  'room.ejercicio.desc': 'Рутины на силу, выносливость и гибкость, с целями.',
  'room.recamara.desc': 'Отслеживай отдых и веди свой личный дневник воспоминаний.',
  'room.descanso.desc': 'Твой сон как ночное небо: расписание, будильник, оценка и журнал ночи.',
  'room.anecdotario.desc': 'Твой личный дневник: воспоминания с фото и настроение дня.',
  'room.despacho.desc':
    'Финансы: бюджет с расходами и доходами (постоянными и переменными), цели (финансовые калькуляторы, сбережения/инвестиции, долги) с симуляторами и рынки в реальном времени.',
  'room.biblioteca.desc': 'Энциклопедия-собеседник: чаты с ИИ, статьи вики и учебные сессии.',
  'room.entretenimiento.desc': 'Архив фильмов, сериалов, книг и настольных игр.',
  'room.sala.desc': 'Планируй поездки: маршрут, расходы, чек-лист и список желаний.',
  'room.jardin.desc': 'Спокойствие: медитации с голосом, дыхание и дневник благодарности.',
  'room.garage.desc': 'Обслуживание твоего транспорта и его сервисные записи.',
  'room.diario.desc': 'Ежедневный дайджест новостей по категориям.',
  'room.hobbies.desc': 'Твои увлечения и творческие проекты.',
  'room.idiomas.desc':
    'Учи языки: репетитор на ИИ, словарь с интервальным повторением, программа по уровням и упражнения.',
  'room.calendario.desc': 'Твой календарь: события и рутины по дням, неделям и месяцам.',
  'room.caminos.desc': 'Прокладывай гоночные трассы, железные дороги и американские горки на карте.',
  'room.canchas.desc': 'Размещай на карте площадки для футбола, тенниса, баскетбола и бейсбола.',
  'room.huerto.desc': 'Готовь грядки, сажай культуры, поливай их и собирай урожай в реальном времени.',
  'room.granja.desc': 'Разводи кур, свиней, коз, овец, коров и лошадей и выращивай для них корм в том же редакторе.',
  'room.ideas.desc':
    'Твой дневник идей и мозговых штурмов, десять форматов карт-схем на свободном холсте (интеллект-карта, дерево, таймлайн, цикл, пирамида, диаграмма Венна…) и восемь диаграмм для принятия решений (плюсы и минусы, силовое поле, SWOT, матрица Эйзенхауэра, дерево решений, тир-лист, взвешенная матрица решений и диаграмма Исикавы) — вручную или с ИИ.',
  'room.metas.desc':
    'Всё, что ты себе наметил, со всего дома: список целей с их подцелями и шагами, планы, которые ИИ предлагает для каждой (этапы с датой, становящиеся настоящими подцелями), и расписание, где всё занимает свой период на оси времени.',
  'room.computo.desc':
    'Компьютерная комната: научный калькулятор со своим справочником формул под рукой (математика, физика и химия — готовые и редактируемые) и восемью режимами — построитель графиков четырёх типов (2D, полярный, параметрический и 3D-поверхность), двоичная и шестнадцатеричная системы, матрицы, системы уравнений, перевод единиц, чаевые и правило трёх; а также таблицы с экспортом в Excel и PDF.',
