  'tut.app-computo--formulario.resumen':
    'Справочник формул — твой. В нём уже есть Математика, Физика и Химия, но это не отдельный каталог: это твои формулы, и ты редактируешь, переносишь или удаляешь их так же, как те, что напишешь.',
