  'tut.app-computo--calculadora.resumen':
    'Научный калькулятор с историей, восемь режимов для всего, что не сводится к одному подсчёту, — среди них построение графиков четырёх типов, — и решатель уравнений, который выдаёт точные корни, когда это возможно.',
